    "expBText": "イ ×【③非常時払】\n「疾病」には、業務外の私傷病も含まれる。\n\n選択肢イ：労働基準法第25条により労働者が非常時払を請求しうる事由のうち、「疾病」とは、業務上の疾病、負傷をいい、業務外のいわゆる私傷病は含まれない。（R元-5D）\n\n確認してみよう：使用者は、労働者が出産、疾病、災害その他厚生労働省令で定める非常の場合の費用に充てるために請求する場合においては、支払期日前であっても、既往の労働に対する賃金を支払わなければならない。",
