    "questionText": "次の文中の□の部分を選択肢の中の適当な語句で埋め、完全な文章とせよ。\n\n労災保険法による保険給付の対象となる業務上の疾病の範囲は、A 別表第１の２で以下の通り定められている。\n(1) 業務上の負傷に起因する疾病\n(2)～(7) 略\n(8) B 業務その他血管病変等を著しく増悪させる業務による脳出血、くも膜下出血、脳梗塞、高血圧性脳症、心筋梗塞、狭心症、心停止（心臓性突然死を含む。）、重篤な心不全若しくは大動脈解離又はこれらの疾病に付随する疾病\n(9) 人の生命にかかわる事故への遭遇その他 C を与える事象を伴う業務による精神及び行動の障害又はこれに付随する疾病\n(10) 前各号に掲げるもののほか、D の指定する疾病\n(11) その他 E 疾病\n\n選択肢\n① 労働者災害補償保険法施行規則　② 労働基準法施行規則　③ 厚生労働省告示　④ 労働安全衛生規則　⑤ 深夜業を含む　⑥ 長期間にわたる長時間の　⑦ 高圧室内　⑧ 有機溶剤を取り扱う　⑨ 心理的に過度の負担　⑩ 著しい疲労の蓄積　⑪ 身体に過重な負担　⑫ 脳機能に影響　⑬ 労働基準監督署長　⑭ 労働衛生指導医　⑮ 都道府県労働局長　⑯ 厚生労働大臣　⑰ 業務の性質を有する　⑱ 業務上発生した　⑲ 業務に起因することの明らかな　⑳ 業務に関連する",
