    "choiceA": "業務上の負傷又は疾病が治って療養の必要がなくなった場合には、その後にその負傷又は疾病が再発しても、新たな業務上の事由によるものでない限り、業務上の負傷は疾病とは認められない。",
    "choiceB": "「血管病変等を著しく増悪させる業務による脳血管疾患及び虚血性心疾患等の認定基準について」（令和３年９月14日付け基発0914第１号／最終改正令和５年10月18日付け基発1018第１号）によると、同認定基準は、業務による明らかな過重負荷を「長期間の過重業務」、「短期間の過重業務」及び「異常な出来事」の3区分に分類し、認定要件としているが、これらの３種類の過重負荷の評価期間は、「長期間の過重業務」については発症前おおむね１年間、「短期間の過重業務」については発症前おおむね３か月、「異常な出来事」については発症直前から前日までの間としている。",
    "choiceC": "「心理的負荷による精神障害の認定基準について」（令和５年９月１日付け基発0901第２号）は、次の①、②、③のいずれの要件も満たす対象疾病（本認定基準で対象とする疾病をいう。以下同じ。）は、労働基準法施行規則別表第１の２号に規定する精神及び行動の障害又はこれに付随する疾病に該当する業務上の疾病として取り扱うこととされている。\n①　対象疾病を発病していること。\n②　対象疾病の発病前おおむね６か月の間に、業務による強い心理的負荷が認められること。\n③　業務以外の心理的負荷及び個体側要因により対象疾病を発病したとは認められないこと。（H30-1A改題）",
