    "choiceE": "複数事業労働者の２以上の事業の業務を要因とする負傷、疾病、障害又は死亡を複数業務要因災害というが、この「複数事業労働者」とは、事業主が同一人でない２以上の事業に使用される労働者をいい、負傷若しくは死亡の原因である事故が発生した日又は診断によって疾病の発生が確定した日において、事業主が同一人でない２以上の事業に使用されていない場合には、複数事業労働者に該当しない。",
    "correctAnswer": "C",
