    "questionText": "次の文中の□の部分を選択肢の中の適当な語句で埋め、完全な文章とせよ。\n\n1 被保険者であって、季節的に雇用されるもののうち次の(1)及び(2)のいずれにも該当しない者（[A]を除く。）を[B]という。\n(1) [C]以内の期間を定めて雇用される者\n(2) 1週間の所定労働時間が20時間以上30時間未満である者\n\n2 [A]が前2月の各月において[D]以上同一の事業主の適用事業に雇用された場合又は同一の事業主の適用事業に[E]以上雇用された場合において、厚生労働省令で定めるところにより公共職業安定所長の認可を受けたときは、その者は、引き続き、[A]となることができる。\n\n選択肢\nA ①日雇特例被保険者 ②日雇労働被保険者 ③日雇労働用特例被保険者 ④短時間労働被保険者\nB ①日雇特例被保険者 ②日雇労働被保険者 ③短期雇用特例被保険者 ④短時間労働被保険者\nC ①3箇月 ②4箇月 ③6箇月 ④1年\nD ①17日 ②18日 ③24日 ④26日\nE ①通算して30日 ②通算して31日 ③継続して30日 ④継続して31日",
