    "expAText": "A: ②日雇労働被保険者\nB: ③短期雇用特例被保険者\nC: ②4箇月\nD: ②18日\nE: ④継続して31日\n\n根拠 法38－Ⅰ、43－Ⅱ、H22厚労告154号\n\n《A、D、Eについて》問題文1のAだけで考えてもわからない場合には、問題文2のAに注目してみよう。Aは、前2月の各月において[②18日]（D）以上同一の事業主の適用事業に雇用された場合又は同一の事業主の適用事業に[④継続して31日]（E）以上雇用された場合には、本来Aではなくなる（一般被保険者などに切り替えられる）のだが、「公共職業安定所長の認可」を受けたときは、「その者は、引き続き[A]となることができる」とあることから、Aには[②日雇労働被保険者]が入ることがわかる。なお、[①日雇特例被保険者]とは、健康保険法3条2項の被保険者のことである。\n《Bについて》問題文1の「季節的に雇用されるもの」というキーワードから、[③短期雇用特例被保険者]が入ることを確認しておこう。",
