    "expEText": "E: ⑲ 離職後最初に出頭した日\n\n【解説】基本手当の受給手続の流れと、手続に際して提出が必要な書類をしっかりと整理しておこう。離職後、最初に管轄公共職業安定所に出頭し、[④求職の申込み]（B）をすることになるが、この際に提出が必要なのは雇用保険[⑨被保険者離職票]（A）であり、受給資格があると認められた場合に交付されるのは雇用保険[②受給資格者証]（C）（個人番号カードを提示して設問文Ⅰの提出をした者であって、雇用保険受給資格通知の交付を希望するものにあっては、雇用保険受給資格通知）である。その後は、原則として[⑲離職後最初に出頭した日]（E）から起算して4週間に1回ずつ出頭し、失業の認定を受けることになるが、その際には、すでに交付を受けている[②受給資格者証]（C）を添えて（当該受給資格者が雇用保険受給資格通知の交付を受けた場合にあっては、個人番号カードを提示して）失業認定申告書を提出した上、[⑰職業の紹介を求め]（D）ることになる。",
    "expESource": "根拠 法15-ⅡⅢ、則19-ⅠⅢ、22-Ⅰ",
