    "expEText": "E: ④ 330日\n\n【解説 B、Eについて】基本手当の受給期間の問題である。「受給期間」とは、基本手当の支給を受けることができる期間をいい、原則として受給資格に係る離職の日の翌日から起算して1年間とされている。離職から求職の申込みまでの期間や待期、自己の労働による収入があった場合など基本手当の支給を受けることができない期間も勘案し、余裕をみて、1年間で受給できる基本手当の日数の限度を「300日」と設定していると考えてみるとよいだろう。すると、所定給付日数が「360日」の者については、「300日＋60日」で受給期間は1年に[②60日]（B）を加えた期間、所定給付日数が[④330日]（E）の者については、「300日＋30日」で受給期間は1年に30日を加えた期間と考えることができる。",
